const unpostedSessions = `-- name: UnpostedSessions :many
SELECT s.id AS session_id, s.event_id, e.number AS event_number, e.name AS event_name, s.session_no, s.name AS session_name, s.session_date, r.name AS room_name,
       s.pax_estimated, s.pax_guaranteed, s.pax_actual, COALESCE(e.posting_mode, st.posting_mode, 'AUTO')::text AS posting_mode, u.full_name AS sales_name,
       EXISTS (SELECT 1 FROM banquet_event_lines l WHERE l.property_id = s.property_id AND l.session_id = s.id AND l.is_active) AS has_lines,
       COALESCE((SELECT cc.code FROM banquet_event_lines l
          LEFT JOIN banquet_line_components lc ON lc.property_id = l.property_id AND lc.line_id = l.id
          JOIN charge_codes cc ON cc.property_id = l.property_id AND cc.id = COALESCE(lc.charge_code_id, l.charge_code_id)
         WHERE l.property_id = s.property_id AND l.session_id = s.id AND l.is_active AND NOT cc.is_active
         ORDER BY cc.code LIMIT 1), '')::text AS inactive_code
FROM banquet_sessions s
JOIN banquet_events e ON e.property_id = s.property_id AND e.id = s.event_id
JOIN users u ON u.tenant_id = e.tenant_id AND u.id = e.sales_user_id
LEFT JOIN banquet_rooms r ON r.property_id = s.property_id AND r.id = s.room_id
LEFT JOIN banquet_settings st ON st.property_id = e.property_id
WHERE e.tenant_id = $1 AND e.property_id = $2 AND e.status = 'DEFINITE' AND s.status = 'ACTIVE' AND s.session_date <= $3::date
  AND NOT EXISTS (SELECT 1 FROM banquet_session_postings p WHERE p.property_id = s.property_id AND p.session_id = s.id)
ORDER BY s.session_date, e.number, s.session_no
`

type UnpostedSessionsParams struct {
	TenantID   int64
	PropertyID int64
	Day        civil.Date
}

type UnpostedSessionsRow struct {
	SessionID     int64
	EventID       int64
	EventNumber   string
	EventName     string
	SessionNo     int32
	SessionName   string
	SessionDate   civil.Date
	RoomName      *string
	PaxEstimated  int32
	PaxGuaranteed *int32
	PaxActual     *int32
	PostingMode   string
	SalesName     string
	HasLines      bool
	InactiveCode  string
}

// The report "sessions not posted" (4.10): active sessions of definite events, dated the business date or earlier, with no posting.
func (q *Queries) UnpostedSessions(ctx context.Context, arg UnpostedSessionsParams) ([]UnpostedSessionsRow, error) {
	rows, err := q.db.Query(ctx, unpostedSessions, arg.TenantID, arg.PropertyID, arg.Day)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []UnpostedSessionsRow{}
	for rows.Next() {
		var i UnpostedSessionsRow
		if err := rows.Scan(
			&i.SessionID,
			&i.EventID,
			&i.EventNumber,
			&i.EventName,
			&i.SessionNo,
			&i.SessionName,
			&i.SessionDate,
			&i.RoomName,
			&i.PaxEstimated,
			&i.PaxGuaranteed,
			&i.PaxActual,
			&i.PostingMode,
			&i.SalesName,
			&i.HasLines,
			&i.InactiveCode,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const updateLine = `-- name: UpdateLine :execrows
UPDATE banquet_event_lines SET description = $1, quantity = $2, unit_price = $3, price_mode = $4, discount_pct = $5,
       discount_amount = $6, discount_by = $7, discount_approved_by = $8, updated_by = $9
WHERE tenant_id = $10 AND property_id = $11 AND event_id = $12 AND id = $13 AND is_active
`

type UpdateLineParams struct {
	Description        string
	Quantity           decimal.Decimal
	UnitPrice          decimal.Decimal
	PriceMode          string
	DiscountPct        *decimal.Decimal
	DiscountAmount     *decimal.Decimal
	DiscountBy         *int64
	DiscountApprovedBy *int64
	ActorID            *int64
	TenantID           int64
	PropertyID         int64
	EventID            int64
	ID                 int64
}

func (q *Queries) UpdateLine(ctx context.Context, arg UpdateLineParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateLine,
		arg.Description,
		arg.Quantity,
		arg.UnitPrice,
		arg.PriceMode,
		arg.DiscountPct,
		arg.DiscountAmount,
		arg.DiscountBy,
		arg.DiscountApprovedBy,
		arg.ActorID,
		arg.TenantID,
		arg.PropertyID,
		arg.EventID,
		arg.ID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

